'use strict';
const FXSND_B64 = {
  fx_boom: '',
  fx_molotov: '',
  fx_gasfire: ''
};
/* ---------- 15в. Записи взрывов и огня (v0.33): fx_boom — граната, клеймор, бочки, баки, подствольник, толстяк;
   fx_molotov — разбитый молотов; fx_gasfire — вспыхнувший бензин. Звук из точки, как у голосов зомби,
   но идёт мимо шины зомби и их лимита. Нет записи — играет старый синтез. ---------- */
const FXA = { gas: 0 };
function fxPlay(name, x, z, vol = 1, rate = 1, o = {}) {
  if (!soundOn() || !Sound.master) return false;
  const b = zvPick(name); if (!b) return false;
  const hear = o.hear || 45, near = o.near || 9;
  let d = 0, pan = 0;
  if (x !== undefined && x !== null && players.length) {
    const e = zvEar(x, z); if (e) { d = e.d; pan = clamp(scrOff(x - e.p.x, z - e.p.z)[0] / 8, -1, 1) * 0.6; }
  }
  if (d > hear) return false;
  const c = Sound.ctx, k = 1 - d / hear;
  const src = c.createBufferSource(); src.buffer = b;
  src.playbackRate.value = rate * (1 + (Math.random() * 2 - 1) * (o.vary === undefined ? 0.06 : o.vary));
  const f = c.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 1400 + 16000 * k * k; f.Q.value = 0.5;
  const g = c.createGain(); g.gain.value = vol / (1 + (d / near) ** 2);
  src.connect(f); f.connect(g);
  if (c.createStereoPanner) { const sp = c.createStereoPanner(); sp.pan.value = pan; g.connect(sp); sp.connect(Sound.master); }
  else g.connect(Sound.master);
  src.start(); return true;
}
{
  const synthBoom = SFX.boom;
  SFX.boomSynth = synthBoom;                                       // светошумовая — свой хлопок, без записи
  SFX.boom = (big = 1, x, z) => {
    if (!soundOn() || !canPlay('boom', 60)) return;
    const s = clamp(big, 0.4, 2);                                   // крупнее взрыв — ниже и громче
    if (fxPlay('fx_boom', x, z, 0.75 + 0.25 * Math.min(1, s), 1 / Math.sqrt(s) * 0.95 + 0.05)) return;
    Sound.last.boom = 0; synthBoom(big);
  };
  SFX.molotov = (x, z) => { if (!soundOn()) return; if (!fxPlay('fx_molotov', x, z, 0.85)) SFX.glass(); };
  SFX.gasFire = (x, z) => {                                        // дорожка вспыхивает по цепочке — один «вух» на 1.2 с
    if (!soundOn() || G.t < FXA.gas) return;
    FXA.gas = G.t + 1.2; fxPlay('fx_gasfire', x, z, 0.8);
  };
}
